/**
 * DB-访问点盘点（分片地基 Phase 0 · Plan 0）——升级为 **semantic-flow contract 级**（Task 3/4）。
 *
 * 全仓每个「拿 db / 携带 db 能力」的点，由类型驱动扫描器（scripts/db-sink-scanner.mjs）枚举成
 * edge，经 classifyPropagation 机器归因，再聚类成 semantic-flow contract 登记于此。这是 shard
 * 路由的权威边界；`check:db-access` 主门（evaluateGate，planned 级）据此断言完整性。
 *
 * **两级 id 并存（诚实标注，不伪造边界）**：
 *   - **legacy 段**（Phase -1 遗留，file 级 id `<file>#<owner>`，无 coveredEdgeIds）：
 *     `check-db-access-ratchet.mjs` 的文件级正则读它的 `file` 字段作**补充网**（挡「新文件引入顶层
 *     拿-db 点」）。不参与 edge 级主门（`collectUnregisteredEdges`/`evaluateGate` 只按 coveredEdgeIds
 *     比较 edge id，legacy id 不含 `::` → 永不匹配真实 edge id → 惰性存在，不伪造覆盖）。
 *   - **edge 段（semantic-flow contract）**：每条聚合一组同 `(file, owner, disposition)` 的 syntax edge，
 *     **列精确 `coveredEdgeIds` + `expectedCount` fingerprint**（禁 owner::* 通配）。新增未覆盖 edge → 门红；
 *     count 变 → 门红；stale coveredEdgeId（edge 已不存在）→ 门红。
 *
 * **两级门（Codex 第 9 轮，evaluateGate `requiredLevel`）**：
 *   - **Plan 0 = `planned` 级（inventory-complete）**：本文件当前满足——全 storing 接收 A 点 +
 *     terminal-escape + unresolved-carrier 都登记 + 每 unresolved-carrier `reviewStatus='classified'` +
 *     `disposition` + `proofObligation`（禁「scanner 不知→planned→绿」退化）+ 每 contract 精确覆盖。
 *     `wiringStatus` 全 `'planned'`（Plan 0 只盘点不接线，**不强求 unresolved=0**——那是 Plan 3）。
 *   - **Plan 3 = `verified` 级（activation-ready，本 Plan 仅定义不跑）**：危险 sink 全 `wiringStatus='verified'`；
 *     `requires-resolver-rewire` 全完成；`resolved-boundary-unproven` 有等价强度证明；terminal-escape 全验证。
 *
 * 归类依据（category，粗归 8 类，保留原盘点语义）：
 *   tenant-isolated / parent-inherited / platform-table / global-worker / explicit-per-request /
 *   longlived-root-capture / module-singleton / root-only（见分片 spec §3-B）。
 *
 * 处置类（disposition，Codex 第 9 轮九值——含四态新增）：
 *   requires-resolver-rewire   组合根/路由注册用 host db 造 carrier，Plan 1/2/3 必改（unresolved-carrier）
 *   resolved-boundary-unproven OS 内核内部 layer 互传，语义来自构造但 scanner 跨函数跟不到（须 proofObligation）
 *   resolver                   长期持有 db 能力的 tenant-scoped 服务，下沉接 resolver.dbForTenant(tenantId)
 *   coordinator                无 tenant_id 平台级表/查询，下沉接 coordinatorDb
 *   mixed-scope                同时含平台级定位 + 租户级写（Auth/SSO/OIDC，spec §4.1 状态机）
 *   per-shard-worker           跨租户扫描的 worker/timer，改 for (const db of resolver.allShardDbs())
 *   root-only                  确无租户归属的顶层构造原语（工厂/路由引擎本身），非拿-host-db 访问点
 *   terminal-escape            能力跨模块/timer/闭包/容器逃逸，须验证逃逸终点仍在正确 shard
 *   known-limitation           Phase 0 明确不下沉（note 须说明「为何不可能错-shard」）
 */

export type DbAccessCategory =
  | 'tenant-isolated'
  | 'parent-inherited'
  | 'platform-table'
  | 'global-worker'
  | 'explicit-per-request'
  | 'longlived-root-capture'
  | 'module-singleton'
  | 'root-only';

export type DbAccessDisposition =
  | 'requires-resolver-rewire'
  | 'resolved-boundary-unproven'
  | 'coordinator'
  | 'root-only'
  | 'terminal-escape'
  | 'resolver'
  | 'mixed-scope'
  | 'per-shard-worker'
  | 'known-limitation';

export interface DbAccessPoint {
  /**
   * 稳定 ID。两级并存（见文件头注释）：
   *   - legacy：`<repo相对路径>#<符号>`（无 `::`；file 级 ratchet 补充网）。
   *   - flow contract：`<repo相对路径>#<owner>::flow::<disposition>`（edge 级主门；带 coveredEdgeIds）。
   */
  readonly id: string;
  readonly file: string;
  readonly category: DbAccessCategory;
  /** 目标处置（必填，九值之一）——放开门据此判断而非 category。 */
  readonly disposition: DbAccessDisposition;
  /** 接线状态（必填）。Plan 0 阶段全部 'planned'（只盘点不接线）。 */
  readonly wiringStatus: 'planned' | 'wired' | 'verified';
  /** scanner 是否机械证明来源（resolved=storing 直接 sink；unresolved=carrier 来源未跟到 resolver 入口）。 */
  readonly provenanceStatus: 'resolved' | 'unresolved';
  /** 是否已定性（Plan 0 全须 'classified'，禁 'unreviewed' 退化——门 condition ④ 强制）。 */
  readonly reviewStatus: 'classified' | 'unreviewed';
  /**
   * 后续证明义务（requires-resolver-rewire / resolved-boundary-unproven / unresolved-carrier /
   * terminal-escape / per-shard-worker / mixed-scope / resolver 覆盖组必填——描述 Plan 1-3 接线时
   * 如何证明「不会错-shard」）。root-only / known-limitation 免。
   */
  readonly proofObligation?: string;
  /**
   * 该 flow contract 精确覆盖的 syntax edge id（**精确覆盖，禁 owner::* 通配**）。
   * legacy 条目无此字段（不参与 edge 门）。
   */
  readonly coveredEdgeIds?: readonly string[];
  /** 覆盖 edge 数 fingerprint（须 === coveredEdgeIds.length；变则门红）。legacy 条目无。 */
  readonly expectedCount?: number;
  readonly note?: string;
}

